import { useCallback, useEffect, useState } from 'react';
import { DATA_MODE } from '../dataMode';
import { localApi } from './local';
import { remoteApi } from './remote';

export type CollectionName = 'users' | 'tournaments' | 'tournament_meta' | 'registrations' | 'transactions' | 'payments' | 'results' | 'notifications';
export type Row = Record<string, unknown> & { id: string };

/** One API for both data sources; which one runs is decided by /lib/dataMode.ts. */
export const api = DATA_MODE === 'real' ? remoteApi : localApi;
export function getDataMode(): 'test' | 'real' { return DATA_MODE; }

/** React hook: the rows of a collection with create/update/remove that refresh the list. */
export function useCollection<T extends Row = Row>(name: CollectionName, query?: { q?: string; limit?: number }) {
  const [items, setItems] = useState<T[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const q = query?.q ?? '';
  const limit = query?.limit ?? 0;
  const refresh = useCallback(async () => {
    try { setItems((await api.list(name, { q, limit: limit || undefined })) as T[]); setError(null); }
    catch (e) { setError((e as Error).message); }
    finally { setLoading(false); }
  }, [name, q, limit]);
  useEffect(() => { void refresh(); return api.subscribe(name, () => { void refresh(); }); }, [name, refresh]);
  return {
    items, loading, error, refresh,
    create: async (data: Omit<T, 'id'>) => { const r = await api.create(name, data as Record<string, unknown>); await refresh(); return r as T; },
    update: async (id: string, patch: Partial<T>) => { const r = await api.update(name, id, patch as Record<string, unknown>); await refresh(); return r as T | null; },
    remove: async (id: string) => { const ok = await api.remove(name, id); await refresh(); return ok; },
  };
}
